from pathlib import Path
import json,hashlib,subprocess,re,urllib.parse,socket,os
root=Path.cwd();out=root/'docs/evidence/step-07/fix-round4';source='59423201ba10ee71c3d1b04cebec69659017b7c7';sha=lambda b:hashlib.sha256(b).hexdigest()
assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==source
sourceledger=json.loads((out/'results/source-files.json').read_text());assert sourceledger['sourceSHA']==source
for p,h in sourceledger['files'].items():assert sha((root/p).read_bytes())==h,p
manifest=json.loads((out/'engineering-manifest.json').read_text());assert manifest['commit']==source
for p,h in manifest['files'].items():assert sha((root/p).read_bytes())==h,p
assert len(manifest['files'])==206
original=json.loads((out/'original-round4.json').read_text());assert sha(original['reportText'].encode())==original['reportSHA256'] and original['payloadsVerified']==430
provenance=json.loads((out/'original-file-provenance.json').read_text());checked=0
for row in provenance['files']:
 p=Path(row['privateOriginal']);p=p if p.is_absolute() else root/p
 assert sha(p.read_bytes())==row['originalSHA256'],str(p)
 q=out/row['evidenceCopy'];assert q.exists(),str(q)
 if 'evidenceSHA256'in row:assert sha(q.read_bytes())==row['evidenceSHA256'],str(q)
 checked+=1
# Secret values are inspected without emitting them.
conf={l.split('=',1)[0]:l.split('=',1)[1] for l in (root/'.env').read_text().splitlines() if '='in l};url=conf.get('DATABASE_URL','');u=urllib.parse.urlparse(url);secrets=[url]+([urllib.parse.unquote(u.password)] if u.password else [])
private=json.loads((root/'.local/step07/fix-round4/final/regression06-private.json').read_text());secrets.append(private['DATABASE_URL'])
for p in out.rglob('*'):
 if not p.is_file():continue
 assert p.suffix in ['.json','.md','.png','.zip'],p
 if p.suffix in ['.json','.md']:
  t=p.read_text()
  if p.suffix=='.json':json.loads(t)
  for secret in secrets:
   if len(secret)>3:assert secret not in t,('secret value detected; filename only',str(p))
assert(root/'.env').stat().st_mode&0o777==0o600
paths=subprocess.check_output(['git','diff','--name-only',source],text=True).splitlines()+subprocess.check_output(['git','ls-files','--others','--exclude-standard'],text=True).splitlines()
assert all(p=='README.md' or p.startswith('docs/') for p in paths),paths
assert set(p for p in paths if not p.startswith('docs/evidence/step-07/fix-round4/'))=={'README.md','docs/engineering/STEP_07_BASELINE.md','docs/engineering/V1_REQUIREMENTS_EVIDENCE.md','docs/reviews/step-07-fix-round-4-coding.md'}
report=root/'docs/reviews/step-07-fix-round-4-coding.md';missing=[]
for name in ['README.md','docs/engineering/STEP_07_BASELINE.md','docs/engineering/V1_REQUIREMENTS_EVIDENCE.md','docs/reviews/step-07-fix-round-4-coding.md']:
 p=root/name
 for target in re.findall(r'\]\(([^)]+)\)',p.read_text()):
  if target.startswith(('https://','http://','#')):continue
  q=(p.parent/target.split('#')[0]).resolve()
  if not q.exists() and q!=out/'ledger.json':missing.append(str(q))
assert not missing,missing
primary=['check','db-migrate','step07','api-integration','dev-privacy','browser-production','browser-development','engineering','pack-sample','step06','legacy-and-native','restored-browser-resource-proof','retained-production-entry','reference-browser','independent-reference','three-cycle-clock','clock-reference','broken-fixture-backup-clone-recovery','all-standard-zip-audit']
commands=json.loads((out/'results/commands.json').read_text())['records']
for name in primary:
 matches=[j for j in commands if j['label']==name];assert len(matches)==1 and matches[0]['sourceSHA']==source and matches[0]['exitCode']==0,name
p=json.loads((out/'results/preservation.json').read_text());assert p['protectedFiles']==2951 and not p['changed']
viewed=json.loads((out/'results/screenshots-viewed.json').read_text())
for j in viewed['images']:assert sha((out/j['path']).read_bytes())==j['sha256']
for mode in ['browser-production','browser-dev']:
 d=json.loads((out/mode/'evidence.json').read_text());assert d['sourceCommit']==source and not d['errors'];assert len(d['pixelChecks'])==8 and all(j['actualSha']==j['independentReferenceSha'] for j in d['pixelChecks'])
 q=json.loads((out/mode/'r2-recovery/poll.json').read_text());assert q['maximumInFlight']==1 and not q['errors']
 rows=json.loads((out/mode/'r2-recovery/ordinary-switch.json').read_text())['rows'];assert len(rows)==3 and all(not j['errors'] and all(r['status']<400 for r in j['responses']) and not any(c['type']=='error' for c in j['console']) for j in rows)
 q=json.loads((out/mode/'r2-recovery/pressure.json').read_text());assert q['attemptsBeforeExplicitReread']<=5 and not q['errors']
for port,expected in [(55476,True),(4376,True),(5276,False)]:
 s=socket.socket();listen=s.connect_ex(('127.0.0.1',port))==0;s.close();assert listen==expected,port
inventory=json.loads((out/'retained-private-inventory.json').read_text())
for item in inventory['files']:
 p=root/item['path'];assert sha(p.read_bytes())==item['sha256'] and p.stat().st_size==item['bytes'],p
record={'privateInventoryFilesVerified':len(inventory['files']),'sourceSHA':source,'docOnlyPaths':len(paths),'sourceFilesVerified':len(sourceledger['files']),'engineeringFilesVerified':206,'engineeringManifestSHA256':sha((out/'engineering-manifest.json').read_bytes()),'protectedHistoricalFiles':2951,'originalProvenanceFilesVerified':checked,'allJsonParsed':True,'actualCredentialScan':'PASS_NO_SECRET_VALUES','originalR4PayloadsVerified':437,'markdownLinksResolved':True,'primaryBoundChecksVerified':len(primary),'originalPrivateProbeErrorPreserved':True,'reportSHA256':sha(report.read_bytes()),'formalReviewsUsed':4,'nextFormalReview':5,'status':'SELF_TESTED_READY_FOR_REVIEW_ROUND5','independentPASS':False,'docsHEADBinding':'Final pure-docs commit recorded in final reply/private progress; no self-referential invented SHA','resourcePorts':{'55476':'own PG retained','4376':'own API retained','5276':'no listener'}}
(out/'handoff-audit.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n')
files={str(p.relative_to(out)):{'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size} for p in sorted(out.rglob('*')) if p.is_file() and p.name!='ledger.json'}
ledger={'candidate':source,'sourceSHA':source,'docsHEADBinding':'Subsequent pureDocs commit; final reply/private coding-progress exact SHA','roundUsed':4,'nextRound':5,'mechanicalLimit':None,'authorization':'2026-10-14','status':'READY_FOR_REVIEW / SELF_TESTED_READY_FOR_REVIEW_ROUND5','relativeRoot':'docs/evidence/step-07/fix-round4','absoluteRoot':str(out),'buildId':manifest['buildId'],'engineeringManifestSHA256':sha((out/'engineering-manifest.json').read_bytes()),'report':{'path':'docs/reviews/step-07-fix-round-4-coding.md','sha256':sha(report.read_bytes()),'bytes':report.stat().st_size},'filesCount':len(files),'files':files,'excluded':'ledger itself; credentials/DB/dump/native core/trace and all assets stay private; .md/JSON formal proof plus essential original PNG/standardZIP','independentReview':'NOT_EXECUTED_BY_CODER','CI':'NOT_EXECUTED_BY_CODER','release':'NOT_EXECUTED_BY_CODER'}
(out/'ledger.json').write_text(json.dumps(ledger,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'files':len(files),'reportSHA256':ledger['report']['sha256'],'ledgerSHA256':sha((out/'ledger.json').read_bytes()),'audit':record},ensure_ascii=False))
